<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';import{useRoute}from'vue-router';import {api,getApiErrorMessage} from '../api/client';
const route=useRoute(),rows=ref([]),error=ref('');const equipmentId=computed(()=>String(route.query.equipmentId||'')),sourceId=computed(()=>String(route.query.sourceId||'')),visibleRows=computed(()=>rows.value.filter(x=>(!equipmentId.value||x.equipmentId===equipmentId.value)&&(!sourceId.value||x.sourceId===sourceId.value)));let timer;async function load(){try{rows.value=(await api.get('/equipment-monitor/dashboard')).data;error.value=''}catch(e){error.value=getApiErrorMessage(e)}}onMounted(()=>{load();timer=setInterval(load,10000)});onBeforeUnmount(()=>clearInterval(timer));
</script><template><section class="space-y-5"><header><h1 class="text-2xl font-black dark:text-white">重點點位即時監控</h1><p class="text-sm text-slate-500">每 10 秒更新；請先在設備點位總覽釘選要監看的點位。</p><div v-if="equipmentId" class="mt-2 flex items-center gap-2 text-sm"><span class="rounded-full bg-cyan-100 px-3 py-1 font-bold text-cyan-800">{{sourceId}} / {{equipmentId}}</span><RouterLink to="/equipment-monitor" class="text-cyan-700 underline">顯示全部設備</RouterLink></div></header><p v-if="error" class="text-red-600">{{error}}</p><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><article v-for="r in visibleRows" :key="r.sourceId+r.equipmentId+r.channelId" class="rounded-xl border p-4 dark:border-slate-700" :class="r.state==='alert'?'border-red-400 bg-red-50 dark:bg-red-950/30':'bg-white dark:bg-slate-800'"><p class="text-xs text-slate-500">{{r.sourceId}} / {{r.equipmentId}}</p><h2 class="font-bold">{{r.name}}</h2><div class="mt-3 text-3xl font-black">{{r.value}} <small class="text-sm">{{r.unit||''}}</small></div><p class="mt-2 text-xs">{{r.channelId}}　{{r.state==='alert'?'超出警戒範圍':r.state==='normal'?'正常':'未設定警戒範圍'}}</p></article></div><p v-if="!visibleRows.length&&!error" class="text-slate-500">{{equipmentId?'此設備尚未釘選任何點位。':'尚未釘選任何點位。'}}</p></section></template>
